import math

def is_power_of_five(x):
    if x <= 0:
        return False
    if x == 1:
        # 5^0 = 1, but 2^n - 3 >= 2^3 - 3 = 5 for n>=3.
        # However, let's keep it general.
        return True

    while x % 5 == 0:
        x //= 5
    return x == 1

solutions = []
for n in range(3, 26):
    value = (2**n) - 3
    if is_power_of_five(value):
        solutions.append(n)
        print(f"n={n}, 2^n - 3 = {value} is a power of 5.")

if not solutions:
    print("No solutions found in the range 3 <= n <= 25.")

print(f"All solutions found: {solutions}")

